//package codeforcespractice;
import java.io.*;
import java.util.*;
public class vanyaandscale {
static long[] a;
static boolean ans;
static int n;
static long leftsum,rightsum;
public static void main(String[] arg) throws Exception
{
    BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
    StringTokenizer st=new StringTokenizer(br.readLine());
    long w=Long.parseLong(st.nextToken());
    long m=Long.parseLong(st.nextToken());
    long limit=(long)1e11;
    a=new long[40];
    int z=1;
    long temp=1;
    a[0]=1;
    if(w<=3)
    {
        System.out.println("YES");
        System.exit(0);
    }
    for(int i=1;i<16;i++)
    {
        a[z]=temp*w;
        temp=temp*w;
        if(temp>limit)
        {
            break;
        }
        z++;
    }

    leftsum=0;
    rightsum=m;
    n=z;
    pos(0);
    //System.out.println("hello");
    if(ans)
    {
        System.out.println("YES");
    }
    else
    {
        System.out.println("NO");
    }

}
public static void  pos(int x)
{
    if(x==n)
    {
        if(leftsum==rightsum)
        {
            //System.out.println("left sum is special "+leftsum+" rightsum is"+rightsum);
            ans=true;
        }
        return;
    }
    //System.out.println("left sum is"+leftsum+" right sum is"+rightsum);
    if(ans)
    {
        return;
    }
    else
    {
        for(int i=0;i<3;i++)
        {
            if(ans)
            {
                return;
            }
            if(i==1)
            {
                leftsum+=a[x];
                pos(x+1);
                leftsum-=a[x];
            }
            else if(i==2)
            {
                rightsum+=a[x];
                pos(x+1);
                rightsum-=a[x];
            }
            else
            {
                pos(x+1);
            }
        }
    }
}
}

